(function(){
'use strict';
const Engine=window.MiyarCompensation;if(!Engine)return;
const KEY='miyar-compensation-scenarios-v1';
const workspace=window.MiyarScenarioWorkspace.create({prefix:'cp',key:KEY,schema:'miyar-compensation-scenario/1.0',calculate:calculateCompensation,values,fill,renderResult:result,bindResult:bind,resultAttribute:'result',fromInput:i=>({...i,targetCompaPercent:i.targetCompaPercent??100})});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function ar(){return document.documentElement.lang!=='en';}function t(a,b){return ar()?a:b;}function money(v,c){if(v===null||v===undefined)return '—';return Number(v).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:2})+' '+esc(c);}
function read(){return workspace.rows();}
function save(v){return workspace.save(v);}
function fieldHint(id){return ({role:[t('يربط الحساب بالمنصب المقصود، بدل نقل تكلفة منصب آخر.','Binds the calculation to the intended position, so another position’s cost is not reused.')],grade:[t('تربط الدرجة المقيّمة بنطاق الجهة؛ المسمى وحده لا يحددها.','Links the evaluated grade to the organization band; a title alone does not determine a grade.')],headcount:[t('يضرب تكلفة الفرد في العدد المطلوب؛ قائمة الشاغلين تستخدم عدد صفوفها.','Multiplies per-person cost by the requested count; an incumbent roster uses its row count.')],currency:[t('تضمن أن الراتب والنطاق بنفس العملة. لا يجري تحويل أسعار الصرف هنا.','Keeps salary and band in the same currency; no exchange-rate conversion is performed.')],source:[t('يوضح من أين جاءت الأرقام، لتتمكن المكافآت من مراجعة النطاق وإصداره.','Identifies where the numbers came from so Total Rewards can review the range and its version.')],min:[t('يكشف الرواتب دون بداية نطاق الدرجة؛ ليس حدًا نظاميًا عامًا.','Identifies pay below the grade-band floor; this is not a general statutory minimum.')],mid:[t('مرجع نسبة المقارنة وميزانية المنصب. أدخل منتصف الجهة أو راجع الافتراض المحسوب.','Anchors compa-ratio and position budgeting. Use the organization midpoint or review the calculated assumption.')],max:[t('يكشف الرواتب فوق نطاق الدرجة دون خفضها تلقائيًا.','Identifies pay above the grade band without an automatic salary reduction.')],current:[t('لنقارن الراتب الفعلي بالنطاق ونحسب أثر التصحيح. اتركه فارغًا لمنصب جديد.','Compares actual pay with the band and calculates correction impact. Leave blank for a new position.')],target:[t('100% يعني استخدام المنتصف للتخطيط؛ لا يقرر زيادة تلقائية لمن هو داخل النطاق.','100% uses the midpoint for planning; it does not automatically raise pay already inside the band.')],policy:[t('يثبت سبب السماح بالتقدم داخل النطاق وفق سياسة الجهة.','Records the organization policy allowing within-band progression.')],evidence:[t('يوضح لماذا يستحق هذا الفرد التقدم؛ موضع الراتب وحده ليس دليل أداء.','Explains why this individual merits progression; salary position alone is not performance evidence.')],asof:[t('يحدد مرحلة نسب التأمينات المعتمدة من المصدر؛ لا يتنبأ بمعدل مستقبلي.','Selects the sourced GOSI rate stage; it does not predict a future rate.')],housing:[t('يضاف للنقد ولأساس الاشتراك وفق السجل؛ الفارغ = صفر.','Adds cash housing to cash pay and the registered contributory base; blank = zero.')],othercash:[t('يضاف للتكلفة النقدية؛ لا يدخل الاشتراك تلقائيًا. الفارغ = صفر.','Adds cash benefits to cost; they do not enter the contributory base automatically. Blank = zero.')],medical:[t('يضيف تكلفة التأمين الصحي على صاحب العمل للفرد؛ الفارغ = صفر.','Adds the employer’s annual medical cost per person; blank = zero.')],service:[t('تحدد نصف شهر أو شهر في تقدير سنة خدمة إضافية. لا تستخدم اسم الموظف.','Determines the half-month or full-month accrual for one additional service year. No employee name is needed.')]})[id]?.[0]||'';}
function field(id,label,value='',attrs='',hint=''){hint=hint||fieldHint(id);return '<label class="cp-field">'+label+'<input id="cp-'+id+'" value="'+esc(value)+'" '+attrs+(hint?' aria-describedby="cp-'+id+'-hint"':'')+'>'+(hint?'<small id="cp-'+id+'-hint" class="cp-hint">'+hint+'</small>':'')+'</label>';}
function pct(v,d=1){if(v===null||!Number.isFinite(Number(v)))return '—';return Number(v).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:d})+'%';}
function values(){const context=matchingPositionContext();return {positionId:context?.positionId||context?.id||'',revision:context?.revision??null,jobFamily:context?.jobFamily||'',bandBinding:context&&reviewedRangeBinding&&String(reviewedRangeBinding.positionId)===String(context.positionId||context.id)&&Number(reviewedRangeBinding.revision)===Number(context.revision)?reviewedRangeBinding:null,payBasis:document.getElementById('cp-basis').value,role:document.getElementById('cp-role').value,grade:context?gradeCode(context.grade||document.getElementById('cp-grade').value):document.getElementById('cp-grade').value,headcount:document.getElementById('cp-headcount').value,currency:document.getElementById('cp-currency').value,period:document.getElementById('cp-period').value,bandSource:document.getElementById('cp-source').value,bandMin:document.getElementById('cp-min').value,bandMid:document.getElementById('cp-mid').value,bandMax:document.getElementById('cp-max').value,targetCompaPercent:document.getElementById('cp-target').value,...advancedValues(),currentSalary:document.getElementById('cp-current').value,oncostPercent:document.getElementById('cp-oncost').value,allowancesPercent:document.getElementById('cp-allowances')?.value??''};}
function fill(e){clearInvalid();clearCostContext();hasUserValues=true;const binding=e.bandBinding;reviewedRangeBinding=binding&&String(binding.positionId)===String(e.positionId)&&Number(binding.revision)===Number(e.revision)?binding:null;if(!reviewedRangeBinding)sourceReviewState=null;document.querySelector('[data-cp-source-review]')?.remove();if(e.positionId&&e.revision){const retained=selectedPositionContext();positionSelection={...(retained||{}),band:retained&&(retained.positionId||retained.id)===e.positionId&&Number(retained.revision)===Number(e.revision)?retained.band:null,positionId:e.positionId,id:e.positionId,revision:e.revision,title:e.role,grade:e.grade,jobFamily:e.jobFamily};}else if(Object.prototype.hasOwnProperty.call(e,'positionId'))positionSelection=null;for(const [k,v] of Object.entries({role:e.role,grade:e.grade,headcount:e.headcount,currency:e.currency,source:e.bandSource,min:e.bandMin,mid:e.bandMid,max:e.bandMax,target:e.targetCompaPercent??100,current:e.currentSalary,oncost:e.oncostPercent,allowances:e.allowancesPercent})){const el=document.getElementById('cp-'+k);if(el)el.value=v??'';}document.getElementById('cp-period').value=e.period||'monthly';document.getElementById('cp-basis').value=e.payBasis||'basic';fillAdvanced(e);refreshProgressivePanels(true);rememberDraft();}
function gradeFromInstitution(role){const I=window.MiyarInstitutionProfile,p=I?.read?.();if(!I||!p||!String(role||'').trim())return'';const g=I.matchGrade(p,role);return g?g.id+' · '+(ar()?g.labelAr:g.labelEn):'';}
const zoneNames={'well-below':['أقل بكثير من المنتصف','Well below midpoint'],below:['دون المنتصف','Below midpoint'],at:['قريب من المنتصف — ليس تقييم أداء','Near midpoint — not a performance rating'],above:['فوق المنتصف','Above midpoint'],'well-above':['أعلى بكثير من المنتصف','Well above midpoint']};
const quartileNames={Q1:['الربع الأول من النطاق','First range quartile'],Q2:['الربع الثاني من النطاق','Second range quartile'],Q3:['الربع الثالث من النطاق','Third range quartile'],Q4:['الربع الرابع من النطاق','Fourth range quartile'],'below-minimum':['دون الحد الأدنى','Below minimum'],'above-maximum':['فوق الحد الأعلى','Above maximum']};
function guidance(v){const r=v.result,i=v.input,c=i.currency;
 if(r.payAction==='roster-review')return [t('مراجعة قائمة الشاغلين','Incumbent roster review'),t('حُسب كل شاغل براتبه الفعلي، ثم جُمعت الآثار. راجع الجدول الفردي قبل أي اعتماد.','Each incumbent uses their actual salary; impacts are summed. Review individual results before approval.')];
 if(r.payAction==='new-position')return [t('تقدير ميزانية لمنصب جديد','New-position budget estimate'),t('الهدف مشتق من المنتصف المعتمد. العرض الفعلي يتطلب سياسة التعيين وخبرة المرشح والاعتماد.','Target is derived from the approved midpoint. An actual offer requires hiring policy, candidate evidence and approval.')];
 if(r.payAction==='increase')return [t('اقتراح تعويض للمراجعة','Compensation proposal for review'),t('زيادة '+money(r.adjustmentPerFte,c)+' لكل FTE ('+pct(r.adjustmentPercent)+') للوصول إلى الهدف.','An increase of '+money(r.adjustmentPerFte,c)+' per FTE ('+pct(r.adjustmentPercent)+') reaches the target.')+(r.adjustmentPercent>15?t(' تعديل كبير: فكّر في جدولته على أكثر من دورة مراجعة.',' Large adjustment: consider phasing it across review cycles.'):'')];
 if(r.payAction==='hold')return [t('تثبيت الراتب داخل النطاق','Hold within-band salary'),t('الموضع داخل النطاق لا يبرر زيادة تلقائية. التقدم الاختياري يحتاج سياسة معتمدة ودليل أداء أو خبرة للفرد.','Range position alone does not justify an increase. Optional progression needs approved policy and individual performance or experience evidence.')];
 if(r.payAction==='below-band')return [t('تصحيح إلى الحد الأدنى لنطاق الجهة','Correction to organization band minimum'),t('أثر التصحيح السنوي: '+money(r.annualMinimumAdjustmentCost,c)+'. هذا تطبيق لسياسة نطاق الجهة للمراجعة، وليس تحديدًا لحد أدنى نظامي. التقدم الإضافي منفصل.','Annual correction cost: '+money(r.annualMinimumAdjustmentCost,c)+'. Organization band policy proposal for review, not a statutory minimum determination. Additional progression is separate.')];
 return [t('أعلى من النطاق — تثبيت للمراجعة','Above band — red-circle / hold for review'),t('لا تخفيض. أوقف زيادات الراتب الأساسي حتى يلحق النطاق، واستخدم مكافآت مقطوعة غير مضافة للأساس عند الأداء المتميز.','No reduction. Pause base increases until the band catches up and use non-consolidated lump sums for strong performance.')];}
function rangeBar(v){const i=v.input,r=v.result,pos=r.currentRangePenetrationPercent,clamp=n=>Math.max(0,Math.min(100,n));return '<div class="cp-range" dir="ltr"><div class="cp-line"><span style="left:0%"></span><span style="left:25%"></span><span style="left:50%"></span><span style="left:75%"></span><span style="left:100%"></span><i class="cp-target" style="left:'+i.targetPenetrationPercent+'%" title="'+t('الهدف','Target')+'"></i>'+(pos===null?'':'<i class="cp-current" style="left:'+clamp(pos)+'%" title="'+t('الراتب الحالي','Current salary')+'"></i>')+'</div><div class="cp-scale"><span>'+t('الحد الأدنى','Min')+'</span><span>'+t('الربع 1','Q1')+'</span><span>'+t('وسط النطاق','Range centre')+'</span><span>'+t('الربع 3','Q3')+'</span><span>'+t('الحد الأعلى','Max')+'</span></div><div class="cp-legend" dir="auto"><span><i class="cp-target"></i>'+t('الهدف','Target')+'</span>'+(pos===null?'':'<span><i class="cp-current"></i>'+t('الراتب الحالي','Current salary')+'</span>')+'</div></div>';}
function diagnosticsView(v){const d=v.bandDiagnostics,spread={undefined:['غير قابل للحساب عندما يكون الحد الأدنى صفرًا','Not computable when the minimum is zero'],narrow:['ضيق — مساحة تقدم محدودة داخل الدرجة','Narrow — limited progression room within the grade'],common:['ضمن حدود الفحص التوضيحية','Within illustrative review thresholds'],wide:['واسع — فكّر في مناطق داخل النطاق أو تقسيم الدرجة','Wide — consider zones within the band or splitting the grade']}[d.spreadAssessment];return '<div class="cp-diagnostics"><strong>'+t('فحص تصميم النطاق','Band design check')+'</strong><ul><li class="'+(d.spreadAssessment==='common'?'ok':'warn')+'">'+t('اتساع النطاق ','Range spread ')+pct(d.rangeSpreadPercent)+' · '+t(...spread)+'</li><li class="'+(d.midpointCentred?'ok':'warn')+'">'+(d.midpointCentred?t('المنتصف في وسط النطاق','Midpoint is centred in the band'):t('المنتصف منحرف '+pct(d.midpointOffsetPercent)+' عن الوسط — تحقق من البيانات','Midpoint is offset '+pct(d.midpointOffsetPercent)+' from the centre — check the data'))+'</li></ul><small>'+t('20–75% حدود تنبيه توضيحية وليست معيارًا سوقيًا. اختلاف المنتصف المعتمد عن وسط النطاق جائز ويحتاج فهم سياسة الجهة.','20–75% are illustrative review triggers, not a market standard. An approved midpoint may differ from the range centre; review the organization policy.')+'</small></div>';}
function costView(v){const r=v.result,i=v.input,c=i.currency;if(v.incumbents||i.employerCosts?.mode==='saudi'||!i.allowancesApplied)return '';return '<div class="cp-cost"><strong>'+t('تكلفة الحزمة السنوية','Annual package cost')+'</strong><dl><dt>'+t('الراتب الأساسي','Basic pay')+'</dt><dd>'+money(r.annualBasePayroll,c)+'</dd><dt>'+t('البدلات الثابتة','Fixed allowances')+' ('+pct(i.allowancesPercent)+')</dt><dd>'+money(r.annualGuaranteedCash-r.annualBasePayroll,c)+'</dd><dt>'+t('الأجر النقدي المضمون','Guaranteed cash')+'</dt><dd>'+money(r.annualGuaranteedCash,c)+'</dd><dt>'+t('تكلفة صاحب العمل الإضافية','Employer on-cost')+' ('+pct(i.oncostPercent)+')</dt><dd>'+money(r.annualEmployerCost-r.annualGuaranteedCash,c)+'</dd></dl></div>';}
function result(v){const r=v.result,i=v.input,c=i.currency,period=t(i.period==='monthly'?'شهري':'سنوي',i.period==='monthly'?'Monthly':'Annual'),g=guidance(v);return '<section class="cp-result"><div class="cp-result-head"><div><span>'+t('المرحلة 3 · نطاق الجهة','PHASE 3 · ORGANIZATION BAND')+'</span><h2>'+esc(i.role||t('سيناريو التعويض','Compensation scenario'))+'</h2><p>'+esc(i.grade||t('الدرجة غير محددة','Grade not specified'))+' · '+period+'</p></div><strong>'+money(r.payAction==='roster-review'?r.annualEmployerCost:r.recommendedSalary??r.targetSalary,c)+'</strong></div><div class="decision-summary"><strong>'+t('ماذا يعني هذا لقرارك؟','What this means for your decision')+'</strong><p>'+esc(g[0]+' — '+g[1]+' '+t('التكلفة السنوية على صاحب العمل: ','Annual employer cost: ')+Number(r.annualEmployerCost).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:0})+' '+c+'.')+'</p></div><div class="cp-metrics"><div><span>'+t('الحد الأدنى','Minimum')+'</span><b>'+money(i.bandMin,c)+'</b></div><div><span>'+t('المنتصف','Midpoint')+'</span><b>'+money(i.bandMid,c)+'</b></div><div><span>'+t('الحد الأعلى','Maximum')+'</span><b>'+money(i.bandMax,c)+'</b></div><div><span>'+t('موضع الهدف داخل النطاق','Target range position')+'</span><b>'+pct(i.targetPenetrationPercent)+'</b></div><div><span>'+t('نسبة المقارنة بالمنتصف (Compa-ratio)','Compa-ratio')+'</span><b>'+(r.compaRatio===null?'—':Number(r.compaRatio).toLocaleString(ar()?'ar-SA':'en-GB',{minimumFractionDigits:2,maximumFractionDigits:2}))+'</b>'+(r.compaZone?'<small>'+t(...zoneNames[r.compaZone])+(r.currentQuartile?' · '+t(...quartileNames[r.currentQuartile]):'')+'</small>':'')+'</div><div><span>'+t('إجمالي تكلفة صاحب العمل سنويًا','Annual employer cost')+'</span><b>'+money(r.annualEmployerCost,c)+'</b></div></div>'+rangeBar(v)+(v.incumbents?'<div class="cp-adjust"><strong>'+t('إجمالي أثر التعديل السنوي للقائمة','Total annual roster adjustment')+': '+money(r.annualAdjustmentCost,c)+'</strong><span>'+t('نسبة المقارنة والفرق الفردي يُراجعان لكل شاغل؛ لا يمثل القائمة راتب واحد.','Review compa-ratio and individual changes per incumbent; one salary does not represent the roster.')+'</span></div>':r.adjustmentPerFte===null?'<p class="cp-note">'+t('لم يُدخل راتب حالي/مرجعي؛ لذلك تبقى نسبة Compa-ratio وتكلفة التعديل غير معروفتين بدل عرض صفر.','No current/reference salary was provided, so compa-ratio and adjustment cost remain unknown rather than displaying zero.')+'</p>':'<div class="cp-adjust"><strong>'+t('الفرق لكل FTE','Difference per FTE')+': '+money(r.adjustmentPerFte,c)+'</strong><span>'+t('الأثر السنوي شامل تكلفة صاحب العمل','Annual adjustment including employer on-cost')+': '+money(r.annualAdjustmentCost,c)+'</span></div>')+'<div class="cp-policy"><strong>'+g[0]+'</strong><p>'+esc(g[1])+'</p><p class="cp-basis">'+t('أساس الحساب: '+(i.payBasis==='total'?'الأجر الإجمالي':'الأجر الأساسي')+'. نسبة التكلفة بحسب النموذج المختار؛ عند اختيار التفصيل السعودي تُحسب البنود من سجل الاشتراك والتاريخ المدخلين.','Pay basis: '+(i.payBasis==='total'?'total cash pay':'basic salary')+'. Employer cost follows the selected model; Saudi breakdown uses the confirmed registration regime and selected date.')+(i.payBasis==='total'&&i.allowancesPercent?t(' البدلات مشمولة في الأجر الإجمالي ولم تُضف مرة أخرى.',' Allowances are already inside total cash pay and were not added again.'):'')+'</p></div>'+costView(v)+advancedResult(v)+diagnosticsView(v)+'<div class="cp-warning"><strong>'+t('ليس Benchmark سوقي','Not a market benchmark')+'</strong><p>'+esc(t('الحساب يستخدم فقط نطاق الراتب الذي أدخلته الجهة ومصدره. الربعان Q1 وQ3 مواضع داخل نطاق الجهة وليست مئينات سوقية. لا يستنتج عدالة الأجر ولا قيمة السوق ولا يصدر اعتماد تعويضات.','The calculation uses only the organization-provided salary band and source. Q1 and Q3 are positions inside the organization band, not market percentiles. It does not infer pay equity, market value or compensation approval.'))+'</p></div><div class="action-row"><button type="button" class="button button-primary" data-cp-save>'+t('حفظ السيناريو','Save scenario')+'</button><button type="button" class="button button-outline" data-cp-export>'+t('تصدير JSON','Export JSON')+'</button></div><p data-cp-status role="status"></p></section>';}
function bind(v){publishCostContext(v);const root=document.querySelector('.cp-result');root.querySelector('[data-cp-save]').onclick=()=>{try{const r=save(v);root.querySelector('[data-cp-status]').textContent=t('حُفظ السيناريو: ','Scenario saved: ')+r.id;}catch(e){workspace.fail(e);}};root.querySelector('[data-cp-export]').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(v,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='miyar-compensation-scenario.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);};}
let selectorGeneration=0;async function positionSelector(){const page=document.querySelector('.cp-page');if(!page||!window.MiyarEnterprise?.positionRegistry)return;const generation=++selectorGeneration,label=document.createElement('label');label.className='cp-field';label.textContent=t('اختر المنصب المحفوظ','Select a saved position');const select=document.createElement('select');select.id='cp-position';label.append(select);page.querySelector('.cp-heading').after(label);select.innerHTML='<option value="">'+t('سيناريو مستقل','Independent scenario')+'</option>';try{const rows=await window.MiyarEnterprise.positionRegistry();if(!select.isConnected||generation!==selectorGeneration)return;for(const p of rows){const option=document.createElement('option');option.value=p.id;option.textContent=window.MiyarEnterprise.positionLabel?window.MiyarEnterprise.positionLabel(p):(p.title||p.content?.title||p.id)+' · v'+p.revision;select.append(option);}const pointer=selectedPositionContext();select.value=pointer?.positionId||pointer?.id||'';select.onchange=async()=>{select.disabled=true;try{if(select.value){positionSelection=undefined;await window.MiyarEnterprise.selectPosition(select.value);}else positionSelection=null;hasUserValues=false;render();}finally{if(select.isConnected)select.disabled=false;}};}catch{label.remove();}}
function render(){if(location.hash!=='#enterprise/compensation')return;const retainedCost=getCostContext();const content=document.getElementById('ent-content');if(!content)return;document.getElementById('enterprise-heading').textContent=t('التعويضات','Compensation');const bc=document.getElementById('breadcrumb-title');if(bc)bc.textContent=t('التعويضات','Compensation');document.querySelectorAll('.nav-link').forEach(x=>x.classList.remove('active'));document.querySelector('[data-comp-nav]')?.classList.add('active');let pending=null;try{pending=JSON.parse(sessionStorage.getItem('miyar-compensation-handoff')||'null');}catch{}if(pending?.positionId&&pending.revision)positionSelection={...pending,id:pending.positionId,title:pending.role};const retainedDraft=prepareDraft(),mayAutoFill=!hasUserValues;content.innerHTML='<section class="cp-page"><div class="cp-heading"><div><span>'+t('المرحلة 3 · التعويضات','PHASE 3 · COMPENSATION')+'</span><h2>'+t('اربط الدرجة بنطاق التعويض المعتمد لدى الجهة','Link the grade to the organization-approved compensation band')+'</h2><p>'+t('معيار لا يخترع رواتب سوقية. أدخل نطاق الجهة ومصدره، ثم احسب موضع الراتب والأثر على التكلفة بشكل قابل للمراجعة.','Miyar does not invent market salaries. Enter the organization band and its source, then calculate salary positioning and cost impact transparently.')+'</p></div><button type="button" class="button button-outline" data-cp-example>'+t('تحميل مثال توضيحي','Load illustrative example')+'</button></div><div class="cp-form">'+field('role',t('الدور / المنصب','Role / position'),pending?.role||selectedPositionContext()?.title||'')+field('grade',t('الدرجة','Grade'),pending?.grade||selectedPositionContext()?.grade||'')+field('headcount',t('عدد أفراد متشابهين — تتجاوزه قائمة الشاغلين','Identical-pay cohort count — roster overrides'),pending?.headcount||1,'type="number" min="1" step="1"')+field('currency',t('العملة','Currency'),'SAR','maxlength="8"')+'<label class="cp-field">'+t('فترة النطاق','Band period')+'<select id="cp-period"><option value="monthly">'+t('شهري','Monthly')+'</option><option value="annual">'+t('سنوي','Annual')+'</option></select></label>'+'<label class="cp-field">'+t('أساس النطاق والراتب','Band and salary basis')+'<select id="cp-basis"><option value="basic">'+t('الراتب الأساسي','Basic salary')+'</option><option value="total">'+t('إجمالي الأجر النقدي','Total cash pay')+'</option></select></label>'+field('source',t('مصدر نطاق الراتب / مرجع الجهة','Salary-band source / organization reference'),'')+field('min',t('الحد الأدنى','Minimum'),'','type="number" min="0" step="any"')+field('mid',t('المنتصف','Midpoint'),'','type="number" min="0" step="any"')+field('max',t('الحد الأعلى','Maximum'),'','type="number" min="0" step="any"')+field('target',t('الهدف كنسبة من المنتصف المعتمد %','Target as % of approved midpoint'),'100','type="number" min="1" max="300" step="1"')+field('current',t('راتب حالي/مرجعي — اختياري','Current/reference salary — optional'),'','type="number" min="0" step="any"')+field('oncost',t('تكلفة صاحب العمل الإضافية %','Employer on-cost %'),'0','type="number" min="0" max="200" step="0.1"',t('حصة صاحب العمل في التأمينات، التأمين الطبي، مخصص نهاية الخدمة ومزايا أخرى — حسب سياسة الجهة.','Employer social-insurance share, medical insurance, end-of-service accrual and other benefits — per organization policy.'))+field('allowances',t('البدلات الثابتة % من الأساسي — اختياري','Fixed allowances % of basic — optional'),'','type="number" min="0" max="200" step="0.1"',t('مثل السكن والنقل حسب سياسة الجهة؛ تُتجاهل إذا كان النطاق على إجمالي الأجر.','For example housing and transport per organization policy; ignored when the band is on total cash pay.'))+'</div><div class="cp-run"><button type="button" class="button button-primary" data-cp-run>'+t('احسب موضع التعويض','Calculate compensation position')+'</button><span id="cp-message" data-cp-message role="status" aria-live="polite" tabindex="-1">'+t('يجب أن يكون النطاق من مصدر داخلي معتمد أو مبرر موثق.','The band must come from an approved internal source or documented rationale.')+'</span></div><div data-cp-result></div></section>';content.querySelector('.cp-form').insertAdjacentHTML('beforeend',advancedFields());sessionStorage.removeItem('miyar-compensation-handoff');content.querySelector('[data-cp-example]').onclick=()=>{positionSelection=null;reviewedRangeBinding=null;workspace.example(ar()?{...Engine.example,...Engine.exampleAr}:Engine.example);};content.querySelector('[data-cp-run]').onclick=()=>workspace.calculate();if(pending)workspace.example({...pending,period:'monthly',currency:'SAR',targetCompaPercent:100,oncostPercent:0});else if(retainedDraft){sourceReviewState=retainedDraft.sourceReview;if(!retainedDraft.sameContext)workspace.example(retainedDraft.input);}progressiveLayout(content);workspace.mount(content);if(retainedDraft?.sameContext&&JSON.stringify(values())!==JSON.stringify(retainedDraft.input)){sourceReviewState=retainedDraft.sourceReview;workspace.example(retainedDraft.input);}const saved=content.querySelector('[data-cp-saved]');if(saved)content.querySelector('[data-cp-result]').after(saved);bindAdvanced(content);positionBanner();refreshProgressivePanels(true);if(mayAutoFill&&!pending)autoFillReviewedPosition();if(sourceReviewState)sourceReviewNote(...sourceReviewState);rememberDraft();if(retainedCost?.costInput)try{if(JSON.stringify(retainedCost.costInput)===JSON.stringify(Engine.evaluate(values()).input)){localStorage.setItem(costContextKey(),JSON.stringify(retainedCost));localStorage.setItem(costRecordKey(retainedCost),JSON.stringify(retainedCost));}}catch{}positionSelector();}

let lastError=null,positionSelection,reviewedRangeBinding=null,hasUserValues=false,activeDraftKey=null,sourceReviewState=null;const drafts=new Map();
function draftKey(){const c=selectedPositionContext();return (window.MiyarEnterprise?.session?.()?.scope||'guest')+'|'+(c?(c.positionId||c.id)+'@'+c.revision+':'+gradeCode(c.grade):'independent');}
function rememberDraft(){if(!document.getElementById('cp-min'))return;activeDraftKey=draftKey();const draft={input:values(),sourceReview:sourceReviewState};drafts.set(activeDraftKey,draft);try{sessionStorage.setItem('miyar-cp-draft-v7:'+activeDraftKey,JSON.stringify(draft));}catch{}}
function prepareDraft(){const key=draftKey();if(activeDraftKey===key){const draft=drafts.get(key);return draft?{...draft,sameContext:true}:null;}workspace.reset();hasUserValues=false;reviewedRangeBinding=null;sourceReviewState=null;activeDraftKey=key;let retained=drafts.get(key);if(!retained)try{retained=JSON.parse(sessionStorage.getItem('miyar-cp-draft-v7:'+key)||'null');}catch{}return retained||null;}
const costContextKey=()=> 'miyar-compensation-cost-context-v1:'+(window.MiyarEnterprise?.session?.()?.scope||'guest');
function costRecordKey(context=selectedPositionContext()){return costContextKey()+':'+(context?.positionId||context?.id||'independent')+'@'+(context?.revision||'')+':'+gradeCode(context?.grade);}
function clearCostContext(){try{localStorage.removeItem(costContextKey());localStorage.removeItem(costRecordKey());}catch{}window.dispatchEvent(new CustomEvent('miyar:compensation-cost-context',{detail:null}));}
function selectedPositionContext(){const current=positionSelection===null?null:positionSelection||window.MiyarEnterprise?.positionContext?.()||window.MiyarPositionContext?.current||window.MiyarPositionContext;return current&&typeof current==='object'&&(current.id||current.positionId)?current:null;}
function gradeCode(value){return String(value||'').split(' · ')[0].trim();}
function matchingPositionContext(){const current=selectedPositionContext(),role=document.getElementById('cp-role')?.value.trim(),grade=document.getElementById('cp-grade')?.value.trim();return current&&role===String(current.title||current.role||'').trim()&&(!current.grade||gradeCode(grade)===gradeCode(current.grade))?current:null;}
function getCostContext(context=selectedPositionContext()){try{const value=JSON.parse(localStorage.getItem(costRecordKey(context))||localStorage.getItem(costContextKey())||'null');return value&&value.scope===(window.MiyarEnterprise?.session?.()?.scope||'guest')?value:null;}catch{return null;}}
function publishCostContext(v){const i=v.input,r=v.result,context={positionId:i.positionId||'',revision:i.revision??null,role:i.role,title:i.role,grade:i.grade,jobFamily:i.jobFamily,currency:i.currency,annualEmployerCost:r.annualEmployerCost,totalEmployerCost:r.annualEmployerCost,headcount:i.headcount,annualEmployerCostPerFte:Number((r.annualEmployerCost/i.headcount).toFixed(2)),calculatedAt:v.createdAt,scope:window.MiyarEnterprise?.session?.()?.scope||'guest',bandSource:i.bandSource,bandBinding:i.bandBinding||null,band:{min:i.bandMin,mid:i.bandMid,max:i.bandMax,currency:i.currency,period:i.period},costInput:JSON.parse(JSON.stringify(i)),components:{annualBasePayroll:r.annualBasePayroll,annualGuaranteedCash:r.annualGuaranteedCash,annualEmployerCharges:r.annualEmployerCost-r.annualGuaranteedCash},source:'compensation-calculation',model:i.employerCosts?.mode||'percentage'};try{localStorage.setItem(costContextKey(),JSON.stringify(context));localStorage.setItem(costRecordKey(context),JSON.stringify(context));}catch{}window.dispatchEvent(new CustomEvent('miyar:compensation-cost-context',{detail:context}));}
function reviewedBand(context){const b=context?.band,source=String(b?.source||b?.bandSource||'').trim();return context?.grade&&b&&Number(b.min)>0&&Number(b.max)>Number(b.min)&&source.length>=5&&['monthly','annual'].includes(b.period)&&b.currency?{...b,min:Number(b.min),max:Number(b.max),source}:null;}
function useReviewedBand(options={}){const previous=values(),c=matchingPositionContext(),b=reviewedBand(c);if(!c||!b)return;const middle=Number(b.mid),explicitMid=Number.isFinite(middle)&&middle>b.min&&middle<b.max,midpoint=explicitMid?middle:(b.min+b.max)/2;reviewedRangeBinding={positionId:c.positionId||c.id,revision:c.revision,grade:gradeCode(c.grade),source:b.source,midpointBasis:explicitMid?'reviewed-band-midpoint':'planning-range-centre',salaryMin:b.min,salaryMax:b.max};const count=Number(c.headcount),headcount=Number.isInteger(count)&&count>0?count:1;workspace.example({positionId:c.positionId||c.id,revision:c.revision,bandBinding:reviewedRangeBinding,jobFamily:c.jobFamily,role:c.title||c.role,grade:gradeCode(c.grade),headcount,payBasis:b.payBasis||'basic',currency:b.currency,period:b.period,bandSource:b.source,bandMin:b.min,bandMid:midpoint,bandMax:b.max,targetCompaPercent:100,currentSalary:'',oncostPercent:0,allowancesPercent:'',progressionEnabled:false,progressionApproved:false,progressionPolicy:'',progressionEvidence:'',rosterCsv:'',employerCosts:null,unitsConfirmed:false});const message=document.querySelector('[data-cp-message]');if(message)message.textContent=explicitMid?t('استُورد نطاق هذا المنصب وإصداره من مراجعة المكافآت. حدّد تكاليف صاحب العمل ثم احسب.','Imported the range reviewed for this position revision. Specify employer costs, then calculate.'):t('استُورد نطاق هذا المنصب وإصداره. المنتصف التخطيطي = (الأدنى + الأعلى) ÷ 2؛ راجع المنتصف وتكاليف صاحب العمل قبل الحساب.','Imported this position revision’s reviewed range. Planning midpoint = (minimum + maximum) / 2; review midpoint and employer costs before calculating.');positionBanner();sourceReviewNote(c,b,previous,options.automatic===true);rememberDraft();}
function positionBanner(){const page=document.querySelector('.cp-page');if(!page)return;let banner=page.querySelector('[data-cp-position-context]');if(!banner){banner=document.createElement('p');banner.dataset.cpPositionContext='';banner.className='cp-context';page.querySelector('.cp-heading').after(banner);}const c=matchingPositionContext();banner.textContent=c?t('المنصب: ','Position: ')+(c.title||c.role)+' · v'+c.revision+' · '+t('الدرجة: ','Grade: ')+(c.grade||t('لم يُقيّم هذا الإصدار','This revision is not evaluated'))+' · '+t('الخطوة 3 من 5','Step 3 of 5'):t('سيناريو مستقل. لربطه بمنصب، اختر المنصب وإصداره في التقييم الوظيفي ثم استخدم الدرجة في التعويضات.','Independent scenario. To bind it to a position, select its revision in job evaluation and use that grade in compensation.');if(reviewedBand(c)){const button=document.createElement('button');button.type='button';button.className='button button-outline';button.dataset.cpReviewedBand='';button.textContent=t('استخدام النطاق المراجع لهذا المنصب','Use this position’s reviewed range');button.onclick=()=>useReviewedBand();banner.append(' ',button);}if(c&&reviewedRangeBinding?.positionId===(c.positionId||c.id)&&Number(reviewedRangeBinding.revision)===Number(c.revision)&&reviewedRangeBinding.midpointBasis==='planning-range-centre'){const note=document.createElement('small');note.textContent=t('المنتصف افتراض تخطيطي محسوب من حدود النطاق؛ ليس منتصفًا معتمدًا مستقلًا.','The midpoint is a planning assumption calculated from range boundaries, not a separately approved midpoint.');banner.append(note);}}
function sourceReviewNote(context,band,previous,automatic,applied=values()){const banner=document.querySelector('[data-cp-position-context]');if(!banner)return;sourceReviewState=[context,band,previous,automatic,applied];document.querySelector('[data-cp-source-review]')?.remove();const note=document.createElement('div');note.dataset.cpSourceReview='';note.className='cp-source-review';note.append(t(automatic?'تعبئة تلقائية من مراجعة هذا المنصب وإصداره: ':'استُورد من مراجعة هذا المنصب وإصداره: ',automatic?'Automatically filled from this position revision’s review: ':'Imported from this position revision’s review: ')+band.source+' · '+(context.positionId||context.id)+' v'+context.revision+' ');const undo=document.createElement('button');undo.type='button';undo.className='button button-outline';undo.dataset.cpUndoFill='';undo.textContent=t('التراجع عن التعبئة','Undo fill');undo.onclick=()=>{const current=values(),restored={...previous};for(const key of Object.keys(current))if(JSON.stringify(current[key])!==JSON.stringify(applied[key]))restored[key]=current[key];reviewedRangeBinding=null;sourceReviewState=null;workspace.example(restored);positionBanner();rememberDraft();};note.append(undo);banner.after(note);}
function autoFillReviewedPosition(){const context=matchingPositionContext(),id=String(context?.positionId||context?.id||'');if(hasUserValues||!context?.revision||!id||id.startsWith('LOCAL-')||!reviewedBand(context)||context.authority!=='approved-rewards'||context.proposedGrade||['cp-min','cp-mid','cp-max','cp-source','cp-current'].some(id=>document.getElementById(id)?.value.trim()))return;useReviewedBand({automatic:true});}
function progressiveLayout(content){const form=content.querySelector('.cp-form'),advanced=form?.querySelector('.cp-advanced');if(!form||!advanced)return;const grouping=(tag,attr,title,ids,hint)=>{const group=document.createElement(tag);group.dataset[attr]='';group.className='cp-input-group';const heading=document.createElement(tag==='details'?'summary':'h3');heading.textContent=title;group.append(heading);if(hint){const p=document.createElement('p');p.className='cp-group-help';p.textContent=hint;group.append(p);}const grid=document.createElement('div');grid.className='cp-input-grid';for(const id of ids){const node=document.getElementById('cp-'+id)?.closest('label');if(node)grid.append(node);}group.append(grid);return group;};
 const essentials=grouping('section','cpEssentials',t('ابدأ بالنطاق والراتب الذي تريد مراجعته','Start with the band and pay to review'),['currency','period','basis','min','mid','max','current'],t('إن اخترت منصبًا تمت مراجعته، نملأ نطاقه من المصدر. وإلا أدخل نطاق جهتك؛ ثم أضف الراتب الحالي للمقارنة أو اتركه لمنصب جديد.','A reviewed position supplies its sourced band. Otherwise enter your organization range, then add actual pay for comparison or leave it blank for a new position.'));form.prepend(essentials);
 const position=grouping('details','cpPositionPanel',t('مراجعة المنصب ومصدر النطاق — المصدر مطلوب','Review position and band source — source required'),['role','grade','headcount','source'],t('عند ربط منصب مراجع نملأ هويته ودرجته وعدده ومرجع النطاق. افتح للتعديل، أو أدخل مصدر جهة موثق لسيناريو مستقل.','A reviewed position supplies its identity, grade, count and range reference. Open to edit, or enter a documented organization source for an independent scenario'));
 const costs=grouping('details','cpCostPanel',t('اختياري: أضف البدلات والتكلفة الإضافية','Optional: add allowances and employer costs'),['oncost','allowances'],t('لتحويل ميزانية الرواتب إلى تكلفة صاحب العمل. استخدم إما نسبة الجهة أو التفصيل السعودي أدناه، كي لا تحسب البنود مرتين.','Turns payroll budgeting into employer cost. Use either the organization percentage or the Saudi breakdown below so components are not counted twice.'));
 const progression=grouping('details','cpProgressionPanel',t('اختياري: غيّر الهدف أو اطلب تقدمًا داخل النطاق','Optional: change the target or review within-band progression'),['target','progression','approved','policy','evidence'],t('يبقى الراتب داخل النطاق ثابتًا في الحساب الأساسي. افتح هذا الجزء فقط عند وجود سياسة ودليل يبرران التقدم.','The basic calculation holds within-band pay. Open this only when policy and evidence support progression.'));
 const checks=grouping('details','cpChecksPanel',t('مراجعة الوحدات للأرقام غير الاعتيادية','Review units for unusual figures'),['units'],t('يطلبها النظام عند الاشتباه في خلط الشهر والسنة أو إدخال أعداد كبيرة؛ لا تحتاجها للبيانات الاعتيادية.','Requested when monthly and annual units may be mixed or scale is unusually large; ordinary inputs do not require it.'));
 advanced.querySelector('h3')?.remove();advanced.querySelector('p')?.remove();advanced.prepend(position,costs,progression,checks);
 for(const [id,message]of Object.entries({period:t('تؤثر على التحويل السنوي: الشهري × 12؛ السنوي لا يضرب مرة أخرى.','Controls annualization: monthly × 12; annual amounts are not multiplied again.'),basis:t('يمنع إضافة البدلات مرتين: هل النطاق أساسي أم يشمل الأجر النقدي؟','Prevents duplicate allowances: is this a basic-pay band or does it include total cash pay?')})){const select=document.getElementById('cp-'+id),small=document.createElement('small');small.id='cp-'+id+'-hint';small.className='cp-hint';small.textContent=message;select?.closest('label')?.append(small);select?.setAttribute('aria-describedby',small.id);}
}
function refreshProgressivePanels(reset=false){const set=(selector,active)=>{const panel=document.querySelector(selector);if(!panel)return;if(active)panel.open=true;else if(reset)panel.open=false;};set('[data-cp-position-panel]',!matchingPositionContext()&&(['role','grade','source'].some(id=>!!document.getElementById('cp-'+id)?.value.trim())||Number(document.getElementById('cp-headcount')?.value)!==1));set('[data-cp-cost-panel]',Number(document.getElementById('cp-oncost')?.value)>0||Number(document.getElementById('cp-allowances')?.value)>0);set('[data-cp-progression-panel]',document.getElementById('cp-progression')?.checked===true||Number(document.getElementById('cp-target')?.value)!==100||!!document.getElementById('cp-policy')?.value.trim()||!!document.getElementById('cp-evidence')?.value.trim());set('[data-cp-checks-panel]',document.getElementById('cp-units')?.checked===true);const saudi=document.getElementById('cp-saudi'),roster=document.getElementById('cp-roster');if(saudi?.checked)saudi.closest('details').open=true;else if(reset&&saudi)saudi.closest('details').open=false;if(roster?.value.trim())roster.closest('details').open=true;else if(reset&&roster)roster.closest('details').open=false;}
window.addEventListener('miyar:session',()=>{hasUserValues=false;positionSelection=undefined;reviewedRangeBinding=null;sourceReviewState=null;activeDraftKey=null;});
document.addEventListener('change',event=>{if(event.target.closest('.cp-form')){hasUserValues=true;refreshProgressivePanels(false);rememberDraft();}});

function clearInvalid(){document.querySelectorAll('.cp-form [aria-invalid]').forEach(el=>{el.removeAttribute('aria-invalid');el.removeAttribute('aria-errormessage');const refs=(el.getAttribute('aria-describedby')||'').split(/\s+/).filter(x=>x&&x!=='cp-message');if(refs.length)el.setAttribute('aria-describedby',refs.join(' '));else el.removeAttribute('aria-describedby');});}
function calculateCompensation(raw){lastError=null;clearInvalid();try{return Engine.evaluate(raw);}catch(error){lastError=error;throw error;}}
function feedback(){const message=document.querySelector('[data-cp-message]');if(!message)return;if(message.dataset.state==='error'&&lastError){const id=lastError.code==='ROSTER_PRIVACY'?'roster':lastError.field||(/roster|incumbent|CSV/i.test(lastError.message)?'roster':null),field=id?document.getElementById('cp-'+id):null;if(lastError.code==='POSITIVE_NUMBER'){const label=field?.closest('label')?.childNodes?.[0]?.textContent?.trim()||lastError.message.split(' must ')[0];message.textContent=t('يجب أن تكون قيمة «'+label+'» أكبر من صفر.',lastError.message);}else if(lastError.message==='Currency is required; enter a recognized currency code')message.textContent=t('حقل العملة مطلوب. أدخل رمزًا مثل SAR.','Currency is required. Enter a code such as SAR.');else if(ar()&&lastError.field){const translated=window.MiyarScenarioWorkspace.errorText(lastError);message.textContent=translated;}if(field){field.setAttribute('aria-invalid','true');field.setAttribute('aria-errormessage','cp-message');field.setAttribute('aria-describedby',[field.getAttribute('aria-describedby'),'cp-message'].filter(Boolean).join(' '));field.closest('details')?.setAttribute('open','');field.focus();field.scrollIntoView?.({block:'center',behavior:'smooth'});}else{message.focus();message.scrollIntoView?.({block:'center',behavior:'smooth'});}}else if(message.dataset.state==='done'){const result=document.querySelector('[data-cp-result]');result?.setAttribute('tabindex','-1');result?.focus();result?.scrollIntoView?.({block:'start',behavior:'smooth'});}positionBanner();}
function gosiTable(b,c){const names={pension:['المعاشات','Pension'],saned:['ساند','SANED'],occupational:['الأخطار المهنية','Occupational hazards']};return '<div class="mp-table-wrap"><table class="cp-gosi-components"><caption>'+t('حصة صاحب العمل لكل فرع من التأمينات','Employer share by insurance branch')+'</caption><thead><tr>'+[t('البند','Component'),t('النسبة','Rate'),t('أساس شهري','Monthly base'),t('المبلغ السنوي','Annual amount'),t('السريان','Effective date'),t('المصدر','Source')].map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+b.gosiComponents.map(x=>'<tr><td>'+t(...names[x.id])+'</td><td>'+x.rate+'%</td><td>'+money(x.monthlyBase,c)+'</td><td>'+money(x.annualAmount,c)+'</td><td>'+esc(x.effectiveFrom||t('نسبة قائمة؛ تاريخ بدايتها غير مبين في المصدر','Existing rate; source does not specify its start date'))+'<small>'+t('مطبقة في ','Applied on ')+esc(x.appliedAsOf)+'</small></td><td><a href="'+esc(x.source.url)+'" target="_blank" rel="noopener">'+t('التأمينات الاجتماعية','GOSI')+'</a><small>'+t('تحقق المصدر: ','Source checked: ')+esc(x.source.checkedOn)+'</small></td></tr>').join('')+'</tbody></table></div>';}
function rosterReview(v){const d=v.rosterDiagnostics;return '<section class="cp-roster-review"><h3>'+t('انضغاط الرواتب وتشتت الدرجة','Salary compression and within-grade dispersion')+'</h3><p>'+t('تنبيه عند وصول راتب المرؤوس إلى 90% من راتب مديره، وعند تشتت نسبي 15% داخل الدرجة. هذه حدود مراجعة وليست حكمًا على عدالة الأجر.','Review triggers: employee salary reaches 90% of manager salary, or grade compa-ratio variation reaches 15%. These thresholds do not determine pay equity.')+'</p>'+(!d.compression.length?'<p>'+t('لا حالات انضغاط ضمن العلاقات المدخلة.','No compression flags among entered reporting relationships.')+'</p>':'<ul>'+d.compression.map(x=>'<li class="warn">'+esc(x.id)+' → '+esc(x.managerId||t('راتب المدير المرجعي','Reference manager salary'))+' · '+pct(x.ratio*100,1)+' · '+(x.status==='salary-inversion'?t('راتب المرؤوس يساوي المدير أو يزيد عليه','Employee salary equals or exceeds manager'):t('تقارب راتب المرؤوس مع المدير','Salary compression review'))+'</li>').join('')+'</ul>')+(d.unresolvedManagers.length?'<p class="cp-warning">'+t('مديرون غير موجودين في القائمة ودون راتب مرجعي: ','Managers absent from roster with no reference salary: ')+d.unresolvedManagers.map(x=>esc(x.id)+' → '+esc(x.managerId)).join(' · ')+'</p>':'')+'<div class="mp-table-wrap"><table><thead><tr>'+[t('الدرجة','Grade'),t('عدد الشاغلين','Incumbents'),t('نسبة المقارنة: أدنى–أعلى','Compa-ratio: min–max'),t('متوسط النسبة','Mean ratio'),t('الانحراف المعياري','Std. deviation'),t('التشتت النسبي','Relative dispersion'),t('خارج النطاق','Outside band')].map(x=>'<th scope="col">'+x+'</th>').join('')+'</tr></thead><tbody>'+d.byGrade.map(g=>'<tr class="'+(g.dispersionReview?'warn':'')+'"><td>'+esc(g.grade)+'</td><td>'+g.count+'</td><td>'+g.minCompaRatio.toFixed(2)+'–'+g.maxCompaRatio.toFixed(2)+'</td><td>'+g.meanCompaRatio.toFixed(2)+'</td><td>'+g.standardDeviation.toFixed(3)+'</td><td>'+pct(g.coefficientOfVariationPercent)+(g.dispersionReview?' · '+t('راجع الفروق','Review differences'):'')+'</td><td>'+g.outOfBand.map(x=>esc(x.id)+' '+(x.status==='below-minimum'?t('دون الحد الأدنى','Below minimum'):t('فوق الحد الأعلى','Above maximum'))).join(' · ')+'</td></tr>').join('')+'</tbody></table></div></section>';}
window.addEventListener('miyar:scenario-result',event=>{if(event.detail?.prefix==='cp')feedback();});
window.addEventListener('miyar:position-context',()=>{positionSelection=undefined;if(location.hash==='#enterprise/compensation'&&activeDraftKey!==draftKey())render();else positionBanner();});
document.addEventListener('input',event=>{if(event.target.closest('.cp-form')){hasUserValues=true;refreshProgressivePanels(false);lastError=null;clearInvalid();if(['cp-min','cp-mid','cp-max','cp-source','cp-grade','cp-role','cp-currency','cp-period'].includes(event.target.id)){reviewedRangeBinding=null;sourceReviewState=null;document.querySelector('[data-cp-source-review]')?.remove();}positionBanner();rememberDraft();clearCostContext();}});

function ensureNav(){const nav=document.querySelector('.sidebar nav.nav-list');if(!nav)return;let link=nav.querySelector('[data-comp-nav]');if(!link){link=document.createElement('a');link.href='#enterprise/compensation';link.className='nav-link';link.dataset.compNav='true';link.innerHTML='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16v12H4zM7 4h10v3M8 12h8m-4-3v6"/></svg><span>'+t('التعويضات','Compensation')+'</span>';const mp=nav.querySelector('[data-manpower-nav]'),grade=nav.querySelector('[data-enterprise-open="grading"]');(mp||grade)?.after(link);}else link.querySelector('span').textContent=t('التعويضات','Compensation');}
// A language switch replaces the shell without a route or enterprise event.
new MutationObserver(ensureNav).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
function injectManpowerLink(){if(location.hash!=='#enterprise/manpower')return;const actions=document.querySelector('.mp-results .action-row'),plan=window.MiyarManpowerWorkbench?.getResult?.();if(!actions||actions.querySelector('[data-cp-from-mp]')||!plan||plan.scenarios.base.final.rawGapFte<=.5)return;const btn=document.createElement('button');btn.type='button';btn.className='button button-outline';btn.dataset.cpFromMp='true';btn.textContent=t('احسب أثر التعويض','Estimate compensation impact');actions.append(btn);btn.onclick=()=>{const current=window.MiyarManpowerWorkbench.getResult();if(!current||current.scenarios.base.final.rawGapFte<=.5)return;sessionStorage.setItem('miyar-compensation-handoff',JSON.stringify({role:current.input.role,positionId:current.input.positionId||'',revision:current.input.positionRevision??current.input.revision??null,jobFamily:current.input.jobFamily||'',grade:current.input.grade||(current.input.positionId?'':gradeFromInstitution(current.input.role)),headcount:current.scenarios.base.final.gapHeadcount}));location.hash='#enterprise/compensation';};}
window.addEventListener('miyar:scenario-result',e=>{if(e.detail.prefix==='mp')injectManpowerLink();});
window.addEventListener('hashchange',()=>setTimeout(()=>{ensureNav();render();injectManpowerLink();},0));window.addEventListener('miyar:navigate',()=>setTimeout(()=>{ensureNav();render();injectManpowerLink();},0));document.addEventListener('click',e=>{const link=e.target.closest('[data-comp-nav]');if(link){e.preventDefault();location.hash='#enterprise/compensation';setTimeout(render,0);}if(e.target.closest('[data-mp-run]'))setTimeout(injectManpowerLink,0);});setTimeout(()=>{ensureNav();render();injectManpowerLink();},0);window.MiyarCompensationWorkbench={KEY,read,render,getResult:()=>workspace.result(),getCostContext,selectedPositionContext,setPositionContext:context=>{positionSelection=context;reviewedRangeBinding=null;positionBanner();},useReviewedBand};
function advancedFields(){const box=(id,label)=>'<label class="cp-check"><input type="checkbox" id="cp-'+id+'">'+label+'</label>';return '<section class="cp-advanced"><h3>'+t('قرار التعويض وأدلة المراجعة','Pay decision and review evidence')+'</h3><p>'+t('لا زيادة تلقائية داخل النطاق. تصحيح الحد الأدنى منفصل عن التقدم الاختياري.','No automatic within-band increases. Minimum correction is separate from optional progression.')+'</p>'+box('progression',t('تضمين تقدم اختياري وفق سياسة الجهة','Include optional progression under organization policy'))+box('approved',t('تحققت من اعتماد سياسة التقدم','I verified progression policy approval'))+field('policy',t('مرجع سياسة التقدم','Progression policy reference'))+field('evidence',t('دليل الأداء أو الخبرة للفرد','Individual performance or experience evidence'))+box('units',t('راجعت الفترة والعملة والوحدات وحجم القائمة','I reviewed period, currency, units and cohort scale'))+'<details><summary>'+t('قائمة الشاغلين — رواتب فعلية لكل فرد','Incumbent roster — actual individual salaries')+'</summary><p>'+t('استخدم رموزًا مستعارة فقط. الحساب محلي في المتصفح، والحفظ اختياري. أضف grade وmanagerId أو managerSalary لفحص الانضغاط. عند اختلاف النطاق أضف bandMin وbandMid وbandMax وbandSource لكل صف.','Use pseudonymous IDs only. Calculation stays in this browser; saving is optional. Add grade and managerId or managerSalary for compression review. Different grade bands need bandMin, bandMid, bandMax and bandSource per row.')+'</p><label class="cp-field">'+t('ملف CSV','CSV file')+'<input type="file" id="cp-roster-file" accept=".csv,text/csv"></label><label class="cp-field">'+t('محتوى CSV — راجعه قبل الحساب','CSV content — review before calculating')+'<textarea id="cp-roster" rows="5" dir="ltr" placeholder="id,currentSalary&#10;P001,25000&#10;P002,23000"></textarea></label><button type="button" class="button button-outline" data-cp-template>'+t('تنزيل قالب الشاغلين','Download roster template')+'</button></details><details><summary>'+t('تفصيل تكلفة صاحب العمل السعودي','Saudi employer-cost breakdown')+'</summary><p>'+t('اختر النظام من سجل المشترك؛ الجنسية وحدها لا تكفي. الحالات الخليجية والخاصة تحتاج حساب المختص. يتطلب أساسي SAR وتصفير نسب العبء والبدلات العامة لمنع الازدواج.','Select the regime from the registration record; nationality alone is insufficient. GCC and special cases need specialist calculation. Requires SAR basic pay and zero generic on-cost/allowance percentages to avoid double counting.')+'</p>'+box('saudi',t('استخدام التفصيل السعودي','Use Saudi breakdown'))+box('applicability',t('راجعت نظام الاشتراك ومكونات الأجر الخاضع للاشتراك','I verified registration regime and contributory wage components'))+'<label class="cp-field">'+t('نظام الاشتراك','Registration regime')+'<select id="cp-regime"><option value="">'+t('اختر من السجل','Choose from record')+'</option><option value="saudi-existing">'+t('سعودي — النظام القائم','Saudi — existing regime')+'</option><option value="saudi-new">'+t('سعودي — مشمول بالنظام الجديد','Saudi — new regime')+'</option><option value="non-saudi">'+t('غير سعودي — الأخطار المهنية فقط','Non-Saudi — occupational hazards only')+'</option></select></label>'+field('asof',t('تاريخ احتساب النسب','Rate calculation date'),'2026-10-05','type="date" min="2024-07-03" max="2028-12-31"')+box('saned',t('ساند منطبق وفق سجل المشترك','SANED applies per registration record'))+field('housing',t('بدل السكن النقدي شهريًا SAR — اختياري','Monthly cash housing SAR — optional'),'','type="number" min="0"')+field('othercash',t('البدلات النقدية الأخرى شهريًا SAR — اختياري','Other monthly cash SAR — optional'),'','type="number" min="0"')+field('contributory',t('مكونات إضافية خاضعة للتأمينات شهريًا SAR — اختياري','Additional monthly GOSI contributory components SAR — optional'),'','type="number" min="0"',t('مثل عمولات مستحقة أو قيمة سكن عيني مراجعة؛ تأكد أنها ضمن النقد أو المزايا المعتمدة.','For reviewed commissions or in-kind housing valuation; reconcile against cash and benefit records.'))+field('medical',t('التأمين الطبي السنوي للفرد SAR — اختياري','Annual medical cost per person SAR — optional'),'','type="number" min="0"')+field('service',t('سنوات الخدمة المكتملة — مطلوب لحساب نهاية الخدمة','Completed years of service — required for EOS'),'0','type="number" min="0" max="60" step="0.01"')+field('eos',t('أجر نهاية الخدمة الشهري — اختياري','EOS monthly wage — optional'),'','type="number" min="0.01"',t('الفارغ يستخدم الأساسي + السكن + البدلات النقدية المدخلة؛ تحقق من الأجر النظامي لدى المختص.','Blank uses basic + entered cash housing + other cash; have a specialist verify the applicable wage.'))+'</details></section>';}
function advancedValues(){const val=id=>document.getElementById('cp-'+id)?.value||'',checked=id=>document.getElementById('cp-'+id)?.checked===true;return {progressionEnabled:checked('progression'),progressionApproved:checked('approved'),progressionPolicy:val('policy'),progressionEvidence:val('evidence'),unitsConfirmed:checked('units'),rosterCsv:val('roster'),employerCosts:checked('saudi')?{mode:'saudi',applicabilityConfirmed:checked('applicability'),regime:val('regime'),asOf:val('asof'),sanedEligible:checked('saned'),housingMonthly:val('housing'),otherMonthly:val('othercash'),contributoryExtraMonthly:val('contributory'),medicalAnnual:val('medical'),serviceYears:val('service'),eosWageMonthly:val('eos')}:null};}
function rosterText(rows){const headers=Engine.rosterColumns;return headers.join(',')+'\n'+rows.map(r=>headers.map(h=>{const v=r[h]??r.employerCosts?.[h]??'';return '"'+String(v).replace(/"/g,'""')+'"';}).join(',')).join('\n');}
function fillAdvanced(e){const b=e.employerCosts||{},values={policy:e.progressionPolicy,evidence:e.progressionEvidence,roster:e.incumbents?rosterText(e.incumbents):e.rosterCsv,regime:b.regime,asof:b.asOf||'2026-10-05',housing:b.housingMonthly,othercash:b.otherMonthly,contributory:b.contributoryExtraMonthly,medical:b.medicalAnnual,service:b.serviceYears,eos:b.eosWageMonthly};for(const [k,v]of Object.entries(values)){const el=document.getElementById('cp-'+k);if(el)el.value=v??'';}for(const [k,v]of Object.entries({progression:e.progressionEnabled,approved:e.progressionApproved,units:e.unitsConfirmed,saudi:b.mode==='saudi',applicability:b.applicabilityConfirmed,saned:b.sanedEligible})){const el=document.getElementById('cp-'+k);if(el)el.checked=v===true;}}
function bindAdvanced(content){const f=content.querySelector('#cp-roster-file');if(!f)return;f.onchange=async()=>{try{const file=f.files[0];if(!file)return;if(file.size>250000)throw Error(t('الحد 250 كيلوبايت','Maximum 250 KB'));const text=await file.text();Engine.parseRoster(text);const target=content.querySelector('#cp-roster');target.value=text;target.dispatchEvent(new Event('input',{bubbles:true}));}catch(e){workspace.fail(e);}finally{f.value='';}};content.querySelector('[data-cp-template]').onclick=()=>{const data=rosterText([{id:'P001',currentSalary:25000,progressionEligible:false,employerCosts:{regime:'saudi-existing',housingMonthly:0,otherMonthly:0,contributoryExtraMonthly:0,medicalAnnual:4000,serviceYears:2,sanedEligible:true}}]);const url=URL.createObjectURL(new Blob(['\uFEFF'+data],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='miyar-incumbents-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);};}
function advancedResult(v){const c=v.input.currency,r=v.result,b=v.employerBreakdown;let html='<div class="cp-policy"><strong>'+t('تصحيح النطاق والتقدم الاختياري — سنويًا','Band correction and optional progression — annual')+'</strong><p>'+t('تصحيح الحد الأدنى: ','Minimum correction: ')+money(r.annualMinimumAdjustmentCost,c)+' · '+t('التقدم الاختياري: ','Optional progression: ')+money(r.annualOptionalProgressionCost,c)+'</p><small>'+t('نسبة المقارنة بالمنتصف لا تقيس أداء الموظف.','Compa-ratio does not measure employee performance.')+'</small></div>';
 if(v.review?.scope==='homogeneous-cohort-assumption')html+='<p class="cp-warning">'+t('افتراض صريح: جميع أفراد هذه المجموعة لهم الراتب والبدلات والنظام نفسه. استخدم قائمة الشاغلين للرواتب المختلفة.','Explicit assumption: everyone in this cohort has identical salary, benefits and regime. Use an incumbent roster for different salaries.')+'</p>';
 if(v.review?.warnings.length)html+='<p class="cp-warning">'+t('تتطلب هذه الأرقام مراجعة الفترة والحجم؛ تم تسجيل تأكيد المستخدم.','These figures trigger period/scale review; user confirmation is recorded.')+'</p>';
 if(b?.mode==='saudi')html+='<div class="cp-cost"><strong>'+t('تفصيل للفرد — تكلفة سنوية عند تاريخ ','Per person — annualized cost at ')+esc(b.asOf)+'</strong><dl>'+[[t('الأجر الخاضع للتأمينات شهريًا','Monthly contributory wage'),b.contributoryWage],[t('تأمينات صاحب العمل سنويًا','Annual employer GOSI'),b.annualGosi],[t('التأمين الطبي السنوي','Annual medical'),b.medicalAnnual],[t('تراكم سنة خدمة إضافية','One further year of service accrual'),b.annualEosServiceAccrual]].map(x=>'<dt>'+x[0]+'</dt><dd>'+money(x[1],c)+'</dd>').join('')+'</dl><p>'+t('معاشات: ','Pension: ')+b.pensionRate+'% · '+t('ساند: ','SANED: ')+b.sanedRate+'% · '+t('أخطار: ','Hazards: ')+b.occupationalRate+'%</p>'+gosiTable(b,c)+'<p>'+t('النسب والأجر ثابتة عند التاريخ المدخل؛ ليس توقعًا لنسب الأشهر القادمة. نهاية الخدمة تقدير تكلفة سنة إضافية، وليست مخالصة نهائية أو التزامًا اكتواريًا وفق IAS 19.','Rates and wage are fixed at the selected date, not a future-month forecast. EOS estimates one more service year, not a termination settlement or IAS 19 actuarial liability.')+'</p>'+b.sources.map(x=>'<a href="'+esc(x.url)+'" target="_blank" rel="noopener">'+esc(x.id)+'</a>').join(' · ')+'</div>';
 if(v.rosterDiagnostics)html+=rosterReview(v);
 if(v.incumbents?.some(x=>x.employerBreakdown?.mode==='saudi'))html+='<div class="cp-roster-gosi">'+v.incumbents.filter(x=>x.employerBreakdown?.mode==='saudi').map(x=>'<details><summary>'+t('تفصيل التأمينات للشاغل ','GOSI details for incumbent ')+esc(x.id)+'</summary>'+gosiTable(x.employerBreakdown,c)+'</details>').join('')+'</div>';
 if(v.incumbents)html+='<div class="cp-roster-results"><h3>'+t('نتائج كل شاغل','Individual results')+'</h3><div class="mp-table-wrap"><table><thead><tr>'+[t('الرمز','ID'),t('الدرجة','Grade'),t('الحالي','Current'),t('نسبة المقارنة','Compa-ratio'),t('الموضع','Band status'),t('المقترح','Proposed'),t('تصحيح / سنة','Correction / year'),t('تقدم / سنة','Progression / year'),t('التكلفة / سنة','Cost / year')].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+v.incumbents.map(x=>'<tr><td>'+esc(x.id)+'</td><td>'+esc(x.input.grade)+'</td><td>'+money(x.input.currentSalary,c)+'</td><td>'+Number(x.result.compaRatio).toLocaleString(ar()?'ar-SA':'en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})+'</td><td>'+t(...({'within-band':['داخل النطاق','Within band'],'below-minimum':['دون النطاق','Below band'],'above-maximum':['فوق النطاق','Above band']}[x.result.bandStatus]||['غير معروف','Unknown']))+'</td>'+[x.result.recommendedSalary,x.result.annualMinimumAdjustmentCost,x.result.annualOptionalProgressionCost,x.result.annualEmployerCost].map(n=>'<td>'+money(n,c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p>'+t('تفاصيل التأمينات ونهاية الخدمة لكل فرد محفوظة في تصدير السيناريو.','Individual GOSI and service-accrual breakdowns are included in the scenario export.')+'</p></div>';
 return html;
}

})();
